sections":[{"title":"Położenie i plaża","text":"Hotel Navarria znajduje się w Limassol, w dzielnicy Agios Tychonas, z widokiem na Morze Śródziemne. Od piaszczystej lub piaszczysto-żwirowej plaży dzieli go zaledwie 100-200 metrów, czyli około 3 minuty spacerem. Leżaki i parasole na plaży są dostępne za opłatą, natomiast przy basenie można z nich korzystać bezpłatnie."},{"title":"Pokoje","text":"Hotel oferuje 130 pokoi, w tym pokoje jednoosobowe, dwuosobowe, trzyosobowe, rodzinne oraz superior, z widokiem na ląd, basen lub morze. Wszystkie pokoje wyposażone są w klimatyzację, balkon, telewizor, telefon, suszarkę do włosów i sejf. Na życzenie dostępne są mini lodówka (za opłatą) oraz czajnik, żelazko i deska do prasowania."},{"title":"Wyżywienie i restauracje","text":"W hotelu znajduje się główna restauracja Berengaria, serwująca dania kuchni międzynarodowej na śniadania, obiady i kolacje. Do dyspozycji gości jest również restauracja tarasowa przy basenie oraz snack bar. Hotel posiada dwa bary: bar przy basenie i Cornaro Bar. Pakiet all inclusive obejmuje posiłki, napoje oraz przekąski w określonych godzinach."},{"title":"Baseny i rekreacja","text":"Hotel dysponuje dwoma odkrytymi basenami ze słodką wodą, w tym jednym z oddzielnym brodzikiem dla dzieci. Na terenie obiektu znajduje się w pełni wyposażona siłownia, oświetlony kort tenisowy oraz stoły do tenisa stołowego i bilarda. Dostępne jest również centrum zdrowia z sauną i gabinetem masażu (dodatkowo płatne).
"},{"title":"Animacje i udogodnienia dla dzieci","text":"Od maja do października hotel oferuje animacje 6 dni w tygodniu, w tym zajęcia dla całej rodziny, takie jak aqua aerobik, turnieje sportowe oraz gry dla dzieci. Wieczorami organizowane są pokazy, w tym wieczór folklorystyczny. Dla najmłodszych dostępny jest oddzielny brodzik oraz gry planszowe."},{"title":"Dla kogo ten hotel","text":"Navarria Hotel jest polecany rodzinom, parom oraz osobom poszukującym komfortowego i niedrogiego wypoczynku. Dzięki dobrej lokalizacji, bliskości plaży i centrum Limassol, stanowi świetną bazę do zwiedzania Cypru. Oferuje dobry stosunek jakości do ceny."}],"pros":["Dobra lokalizacja, blisko plaży i przystanku autobusowego","Czyste i odnowione pokoje z wygodnymi łóżkami","Przyjazny i profesjonalny personel","Dobre jedzenie, szczególnie śniadania","Duży i czysty basen"],"cons":["Niektóre wnętrza i umeblowanie mogą być przestarzałe","Potencjalny hałas z otoczenia","Ograniczony dostęp do gniazdek elektrycznych","Leżaki i parasole na plaży płatne","Brak aquaparku"],"faq":[{"q":"Jak daleko jest do plaży od hotelu Navarria?","a":"Hotel Navarria jest położony około 100-200 metrów od piaszczystej lub piaszczysto-żwirowej plaży, co zajmuje około 3 minuty spacerem."},{"q":"Jak daleko jest hotel od lotniska?","a":"Hotel znajduje się około 60-67 km od lotniska w Larnace (LCA) i około 60-61 km od lotniska w Pafos (PFO)."},{"q":"Czy hotel Navarria oferuje aquapark lub zjeżdżalnie?","a":"Nie, hotel Navarria nie posiada aquaparku ani zjeżdżalni na swoim terenie."},{"q":"Czy hotel jest odpowiedni dla rodzin z dziećmi?","a":"Tak, hotel jest przyjazny rodzinom i oferuje oddzielny brodzik dla dzieci, gry planszowe oraz animacje z zajęciami dla całej rodziny."},{"q":"Czy w hotelu jest dostęp do Wi-Fi?","a":"Tak, w całym hotelu, zarówno w pokojach, jak i w częściach publicznych, dostępne jest bezpłatne Wi-Fi."},{"q":"Czy hotel jest tylko dla dorosłych?","a":"Nie, hotel Navarria jest przyjazny rodzinom i nie jest przeznaczony wyłącznie dla dorosłych."}],"address":"Verginas 14, Limassol, 4532, Cypr","adultsOnly":false,"airportKm":60,"airportName":"Larnaca (LCA) lub Pafos (PFO)","amenities":["Centrum fitness/siłownia","Kort tenisowy","Tenis stołowy","Bilard/snooker","Sauna","Gabinet masażu","Salon piękności/fryzjer"],"animations":true,"aquapark":false,"area":"Agios Tychonas (Agios Tychon)","bars":2,"beachDistanceM":150,"beachType":"Piaszczysta lub piaszczysto-żwirowa","centerKm":4.5,"goodFor":["Rodziny","Pary","Osoby szukające niedrogiego i wygodnego wypoczynku"],"gym":true,"heatedPool":null,"kidsClub":false,"lat":null,"lon":null,"opened":1990,"pools":2,"privateBeach":false,"renovated":2004,"restaurants":3,"roomTypes":["Pokój jednoosobowy z klimatyzacją, balkonem, TV, telefonem, suszarką do włosów, sejfem","Pokój dwuosobowy/twin (widok na ląd, basen, morze) z klimatyzacją, balkonem, TV, telefonem, suszarką do włosów, sejfem","Pokój trzyosobowy z klimatyzacją, balkonem, TV, telefonem, suszarką do włosów, sejfem","Pokój rodzinny (widok na góry, morze) z klimatyzacją, balkonem, TV, telefonem, suszarką do włosów, sejfem","Pokój superior (widok na ląd, morze) z klimatyzacją, balkonem, TV, telefonem, suszarką do włosów, sejfem"],"rooms":130,"spa":true,"wifi":true}
